export { AuthPage, type AuthPageMode } from "@/auth/auth-page";
export { AuthProvider, useAuth } from "@/auth/auth-provider";
export { isStitchEmail } from "@/auth/authorization";
export { ProtectedRoute, StitchEmailGate, StitchOnlyRoute } from "@/auth/guards";

import { Alert, AlertDescription } from "@/components/ui/alert";

export function AuthError({ message }: { message: string }) {
  return (
    <Alert variant="destructive">
      <AlertDescription>{message}</AlertDescription>
    </Alert>
  );
}

"use client";

import { type FormEvent, useState } from "react";
import { Link, Navigate, useLocation } from "react-router";

import { AuthError } from "@/auth/auth-error";
import { useAuth } from "@/auth/auth-provider";
import { FullPageSpinner } from "@/auth/guards";
import { SignUpForm } from "@/auth/sign-up-form";
import { TotpEnrollmentForm } from "@/auth/totp-enrollment-form";
import {
  AuthShell,
  AuthShellBrand,
  AuthShellCard,
  AuthShellContent,
  AuthShellFooter,
  AuthShellHeader,
} from "@/components/ui/auth-shell";
import { Button } from "@/components/ui/button";
import { CardDescription } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { InputOTP, InputOTPGroup, InputOTPSlot } from "@/components/ui/input-otp";
import { Label } from "@/components/ui/label";
import { BrandLockup } from "@/components/ui/stitch-brand";

export type AuthPageMode = "sign-in" | "sign-up";

export function AuthPage({ appName, mode = "sign-in" }: { appName: string; mode?: AuthPageMode }) {
  const auth = useAuth();
  const location = useLocation();
  const from = getReturnPath(location.state);
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [code, setCode] = useState("");
  const [error, setError] = useState("");
  const [submitting, setSubmitting] = useState(false);

  if (auth.loading) return <FullPageSpinner label="Checking your session" />;
  if (auth.status === "authenticated") return <Navigate replace to={from} />;

  async function submitCredentials(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setError("");
    setSubmitting(true);
    try {
      const message = await auth.signIn(email.trim(), password);
      if (message) setError(message);
    } catch (cause) {
      setError(cause instanceof Error ? cause.message : "Sign in failed.");
    } finally {
      setSubmitting(false);
    }
  }

  async function submitCode(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setError("");
    setSubmitting(true);
    try {
      const message = await auth.verifyMfa(code);
      if (message) setError(message);
    } catch (cause) {
      setError(cause instanceof Error ? cause.message : "MFA verification failed.");
    } finally {
      setSubmitting(false);
    }
  }

  async function signOut() {
    setError("");
    setSubmitting(true);
    try {
      const message = await auth.signOut();
      if (message) setError(message);
    } catch (cause) {
      setError(cause instanceof Error ? cause.message : "Sign out failed.");
    } finally {
      setSubmitting(false);
    }
  }

  const content =
    auth.status === "mfa-required" ? (
      <MfaChallengeForm
        code={code}
        error={error}
        onCodeChange={setCode}
        onSignOut={() => void signOut()}
        onSubmit={submitCode}
        submitting={submitting}
      />
    ) : auth.status === "mfa-setup-required" ? (
      <TotpEnrollmentForm
        appName={appName}
        onSignOut={() => void signOut()}
        signingOut={submitting}
      />
    ) : auth.status === "error" ? (
      <AuthError message={error || auth.error?.message || "Your session could not be verified."} />
    ) : mode === "sign-up" ? (
      <SignUpForm />
    ) : (
      <CredentialsForm
        email={email}
        error={error}
        onEmailChange={setEmail}
        onPasswordChange={setPassword}
        onSubmit={submitCredentials}
        password={password}
        submitting={submitting}
      />
    );

  return (
    <AuthShell className="[&_[data-slot=auth-shell-container]]:gap-4">
      <AuthShellBrand className="justify-start px-3">
        <BrandLockup applicationName={appName} markClassName="size-6" />
      </AuthShellBrand>
      <AuthShellCard>
        <AuthShellHeader className="gap-1 text-left">
          <h1 className="font-heading leading-none font-semibold">{getTitle(auth.status, mode)}</h1>
          {auth.status === "error" ? null : (
            <CardDescription>{getDescription(auth.status, mode, appName)}</CardDescription>
          )}
        </AuthShellHeader>
        <AuthShellContent>{content}</AuthShellContent>
      </AuthShellCard>
      {auth.status === "signed-out" ? (
        <AuthModeSwitch mode={mode} returnState={location.state} />
      ) : null}
    </AuthShell>
  );
}

function AuthModeSwitch({ mode, returnState }: { mode: AuthPageMode; returnState: unknown }) {
  const signingUp = mode === "sign-up";
  return (
    <AuthShellFooter>
      {signingUp ? "Already have an account? " : "Need an account? "}
      <Link
        className="underline underline-offset-3 hover:text-foreground"
        state={returnState}
        to={signingUp ? "/auth" : "/auth/sign-up"}
      >
        {signingUp ? "Sign in" : "Create one"}
      </Link>
    </AuthShellFooter>
  );
}

function CredentialsForm({
  email,
  error,
  onEmailChange,
  onPasswordChange,
  onSubmit,
  password,
  submitting,
}: {
  email: string;
  error: string;
  onEmailChange: (value: string) => void;
  onPasswordChange: (value: string) => void;
  onSubmit: (event: FormEvent<HTMLFormElement>) => void;
  password: string;
  submitting: boolean;
}) {
  return (
    <form className="space-y-4 pt-1" onSubmit={onSubmit}>
      <div className="space-y-1.5">
        <Label htmlFor="email">Email</Label>
        <Input
          autoComplete="username"
          id="email"
          onChange={(event) => onEmailChange(event.target.value)}
          required
          type="email"
          value={email}
        />
      </div>
      <div className="space-y-1.5">
        <Label htmlFor="password">Password</Label>
        <Input
          autoComplete="current-password"
          id="password"
          onChange={(event) => onPasswordChange(event.target.value)}
          required
          type="password"
          value={password}
        />
      </div>
      {error ? <AuthError message={error} /> : null}
      <Button className="w-full" disabled={submitting} type="submit">
        {submitting ? "Signing in…" : "Sign in"}
      </Button>
    </form>
  );
}

function MfaChallengeForm({
  code,
  error,
  onCodeChange,
  onSignOut,
  onSubmit,
  submitting,
}: {
  code: string;
  error: string;
  onCodeChange: (value: string) => void;
  onSignOut: () => void;
  onSubmit: (event: FormEvent<HTMLFormElement>) => void;
  submitting: boolean;
}) {
  return (
    <form className="space-y-4 pt-1" onSubmit={onSubmit}>
      <div className="space-y-1.5">
        <Label className="block text-center" htmlFor="mfa-code">
          Authentication code
        </Label>
        <div className="flex justify-center">
          <InputOTP
            autoComplete="one-time-code"
            disabled={submitting}
            id="mfa-code"
            maxLength={6}
            onChange={onCodeChange}
            value={code}
          >
            <InputOTPGroup>
              {Array.from({ length: 6 }, (_, index) => (
                <InputOTPSlot index={index} key={index} />
              ))}
            </InputOTPGroup>
          </InputOTP>
        </div>
      </div>
      {error ? <AuthError message={error} /> : null}
      <div className="flex gap-2">
        <Button
          className="flex-1"
          disabled={submitting}
          onClick={onSignOut}
          type="button"
          variant="outline"
        >
          Start over
        </Button>
        <Button className="flex-1" disabled={submitting || code.length !== 6} type="submit">
          {submitting ? "Verifying…" : "Verify"}
        </Button>
      </div>
    </form>
  );
}

function getReturnPath(state: unknown) {
  if (!state || typeof state !== "object" || !("from" in state)) return "/";
  const from = state.from;
  if (!from || typeof from !== "object" || !("pathname" in from)) return "/";
  return typeof from.pathname === "string" && from.pathname.startsWith("/") ? from.pathname : "/";
}

function getTitle(status: string, mode: AuthPageMode) {
  if (status === "mfa-required") return "Verify your identity";
  if (status === "mfa-setup-required") return "Set up authentication";
  if (status === "error") return "Session verification failed";
  return mode === "sign-up" ? "Create your account" : "Sign in";
}

function getDescription(status: string, mode: AuthPageMode, appName: string) {
  if (status === "mfa-required") return "Enter the code from your authenticator.";
  if (status === "mfa-setup-required") {
    return `${appName} requires a TOTP authenticator.`;
  }
  return mode === "sign-up"
    ? "Use the email a Stitch administrator added to your organization."
    : "Use your Stitch platform credentials.";
}

"use client";

import type { Session, User } from "@supabase/supabase-js";
import { useQueryClient } from "@tanstack/react-query";
import {
  createContext,
  type ReactNode,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
} from "react";

import {
  type AuthState,
  type AuthStatus,
  challengeAndVerifyTotp,
  createAuthErrorState,
  describeAuthError,
  initialAuthState,
  resolveSessionState,
  type SignUpInput,
  type SignUpOutcome,
  toError,
} from "@/auth/auth-state";
import { getSupabaseClient } from "@/lib/supabase";

type AuthContextValue = {
  confirmTotpEnrollment: (factorId: string, code: string) => Promise<string | null>;
  error: Error | null;
  loading: boolean;
  mfaRequired: boolean;
  mfaSetupRequired: boolean;
  retry: () => Promise<void>;
  session: Session | null;
  signIn: (email: string, password: string) => Promise<string | null>;
  signOut: () => Promise<string | null>;
  signUp: (input: SignUpInput) => Promise<SignUpOutcome>;
  status: AuthStatus;
  user: User | null;
  verifyMfa: (code: string) => Promise<string | null>;
};

const AuthContext = createContext<AuthContextValue | null>(null);

// A before-user-created hook rejects anyone who is not already a member of the organization, and
// Supabase relays that as an empty error, so state the remedy instead of the missing detail.
const signUpRejected =
  "This account could not be created. Your email has to be added to the organization first. Ask a Stitch administrator, then sign up again.";

export function AuthProvider({ children }: { children: ReactNode }) {
  const queryClient = useQueryClient();
  const [state, setState] = useState<AuthState>(initialAuthState);
  const mounted = useRef(false);
  const mfaRequest = useRef<Promise<string | null> | null>(null);
  const principal = useRef<string | null | undefined>(undefined);
  const requestSequence = useRef(0);
  const stateRef = useRef<AuthState>(initialAuthState);

  const commit = useCallback((requestId: number, nextState: AuthState) => {
    if (mounted.current && requestId === requestSequence.current) {
      stateRef.current = nextState;
      setState(nextState);
    }
  }, []);

  const updatePrincipal = useCallback(
    (requestId: number, session: Session | null) => {
      if (requestId !== requestSequence.current) return;
      const nextPrincipal = session?.user.id ?? null;
      if (principal.current === undefined || principal.current !== nextPrincipal) {
        queryClient.clear();
      }
      principal.current = nextPrincipal;
    },
    [queryClient],
  );

  const inspectSession = useCallback(
    async (session: Session | null, requestId = ++requestSequence.current, showLoading = true) => {
      updatePrincipal(requestId, session);
      if (showLoading) {
        commit(requestId, {
          error: null,
          factorId: null,
          session,
          status: "loading",
        });
      }

      let nextState = createAuthErrorState(
        new Error("Your session could not be verified."),
        session,
      );
      try {
        nextState = await resolveSessionState(session);
      } catch (error) {
        nextState = createAuthErrorState(error, session);
      } finally {
        commit(requestId, nextState);
      }
      return nextState;
    },
    [commit, updatePrincipal],
  );

  const refreshSession = useCallback(async () => {
    const requestId = ++requestSequence.current;
    commit(requestId, {
      error: null,
      factorId: null,
      session: null,
      status: "loading",
    });

    let nextState: AuthState | null = null;
    try {
      const { data, error } = await getSupabaseClient().auth.getSession();
      if (error) {
        throw new Error(`Your session could not be loaded: ${error.message}`, { cause: error });
      }
      nextState = await inspectSession(data.session, requestId);
    } catch (error) {
      nextState = createAuthErrorState(error, null);
    } finally {
      if (nextState) commit(requestId, nextState);
    }
  }, [commit, inspectSession]);

  useEffect(() => {
    mounted.current = true;
    let unsubscribe: () => void = () => undefined;

    try {
      const {
        data: { subscription },
      } = getSupabaseClient().auth.onAuthStateChange((event, nextSession) => {
        globalThis.setTimeout(() => {
          if (!mounted.current) return;
          const current = stateRef.current;
          const isSamePrincipalRefresh =
            nextSession !== null &&
            current.status !== "loading" &&
            current.session?.user.id === nextSession.user.id &&
            (event === "SIGNED_IN" || event === "TOKEN_REFRESHED");
          void inspectSession(nextSession, undefined, !isSamePrincipalRefresh);
        }, 0);
      });
      unsubscribe = () => subscription.unsubscribe();
    } catch (error) {
      const requestId = ++requestSequence.current;
      commit(requestId, createAuthErrorState(error, null));
    }

    void refreshSession();
    return () => {
      mounted.current = false;
      requestSequence.current += 1;
      unsubscribe();
    };
  }, [commit, inspectSession, refreshSession]);

  const signIn = useCallback(
    async (email: string, password: string) => {
      const requestId = ++requestSequence.current;
      commit(requestId, {
        error: null,
        factorId: null,
        session: null,
        status: "loading",
      });

      let nextState: AuthState | null = null;
      let message: string | null = null;
      try {
        const { data, error } = await getSupabaseClient().auth.signInWithPassword({
          email,
          password,
        });
        if (error) {
          message = describeAuthError(error.message);
          nextState = {
            error: null,
            factorId: null,
            session: null,
            status: "signed-out",
          };
        } else {
          nextState = await inspectSession(data.session, requestId);
          if (nextState.status === "error") message = nextState.error?.message ?? "Sign in failed.";
        }
      } catch (error) {
        message = toError(error, "Sign in failed.").message;
        nextState = {
          error: null,
          factorId: null,
          session: null,
          status: "signed-out",
        };
      } finally {
        if (nextState) commit(requestId, nextState);
      }
      return message;
    },
    [commit, inspectSession],
  );

  // A failed sign up leaves the signed-out state untouched so the form keeps what was typed.
  const signUp = useCallback(
    async ({ email, firstName, lastName, password }: SignUpInput): Promise<SignUpOutcome> => {
      try {
        const { data, error } = await getSupabaseClient().auth.signUp({
          email,
          options: {
            data: { first_name: firstName, has_password: true, last_name: lastName },
          },
          password,
        });
        if (error) {
          return { message: describeAuthError(error.message, signUpRejected), status: "error" };
        }
        // Supabase withholds the session until the address is confirmed.
        if (!data.session) return { message: null, status: "confirmation-required" };

        const nextState = await inspectSession(data.session, ++requestSequence.current);
        return nextState.status === "error"
          ? { message: nextState.error?.message ?? "Sign up failed.", status: "error" }
          : { message: null, status: "signed-up" };
      } catch (error) {
        return { message: toError(error, "Sign up failed.").message, status: "error" };
      }
    },
    [inspectSession],
  );

  const signOut = useCallback(async () => {
    const currentSession = state.session;
    const requestId = ++requestSequence.current;
    commit(requestId, {
      error: null,
      factorId: null,
      session: currentSession,
      status: "loading",
    });

    let nextState: AuthState | null = null;
    let message: string | null = null;
    try {
      const { error } = await getSupabaseClient().auth.signOut();
      if (error) {
        throw new Error(`Sign out failed: ${error.message}`, { cause: error });
      }
      updatePrincipal(requestId, null);
      queryClient.clear();
      nextState = await inspectSession(null, requestId);
    } catch (error) {
      const normalized = toError(error, "Sign out failed.");
      message = normalized.message;
      nextState = createAuthErrorState(normalized, currentSession);
    } finally {
      if (nextState) commit(requestId, nextState);
    }
    return message;
  }, [commit, inspectSession, queryClient, state.session, updatePrincipal]);

  const reloadVerifiedSession = useCallback(
    async (requestId: number) => {
      const { data, error } = await getSupabaseClient().auth.getSession();
      if (error) {
        throw new Error(`Your verified session could not be loaded: ${error.message}`, {
          cause: error,
        });
      }
      return inspectSession(data.session, requestId);
    },
    [inspectSession],
  );

  // Enrollment verification keeps the caller's state so a rejected code does not discard the
  // in-progress QR code, which Supabase cannot reissue for the same factor.
  const confirmTotpEnrollment = useCallback(
    async (factorId: string, code: string) => {
      const currentSession = stateRef.current.session;
      try {
        const verificationMessage = await challengeAndVerifyTotp(factorId, code);
        if (verificationMessage) return verificationMessage;

        const nextState = await reloadVerifiedSession(++requestSequence.current);
        return nextState.status === "error"
          ? (nextState.error?.message ?? "Authenticator verification failed.")
          : null;
      } catch (error) {
        const normalized = toError(error, "Authenticator verification failed.");
        commit(++requestSequence.current, createAuthErrorState(normalized, currentSession));
        return normalized.message;
      }
    },
    [commit, reloadVerifiedSession],
  );

  const verifyMfa = useCallback(
    (code: string) => {
      if (state.status !== "mfa-required" || !state.factorId || !state.session) {
        return Promise.resolve("No verified authenticator is available.");
      }
      if (mfaRequest.current) return mfaRequest.current;
      const factorId = state.factorId;

      const request = (async () => {
        const previousState = state;
        const requestId = ++requestSequence.current;
        commit(requestId, { ...state, status: "loading" });

        let nextState: AuthState = previousState;
        let message: string | null = null;
        try {
          message = await challengeAndVerifyTotp(factorId, code);
          if (!message) {
            nextState = await reloadVerifiedSession(requestId);
            if (nextState.status === "error") {
              message = nextState.error?.message ?? "MFA verification failed.";
            }
          }
        } catch (error) {
          const normalized = toError(error, "MFA verification failed.");
          message = normalized.message;
          nextState = createAuthErrorState(normalized, previousState.session);
        } finally {
          commit(requestId, nextState);
        }
        return message;
      })();
      const trackedRequest = request.finally(() => {
        if (mfaRequest.current === trackedRequest) mfaRequest.current = null;
      });
      mfaRequest.current = trackedRequest;
      return trackedRequest;
    },
    [commit, reloadVerifiedSession, state],
  );

  const value = useMemo<AuthContextValue>(
    () => ({
      confirmTotpEnrollment,
      error: state.error,
      loading: state.status === "loading",
      mfaRequired: state.status === "mfa-required",
      mfaSetupRequired: state.status === "mfa-setup-required",
      retry: refreshSession,
      session: state.session,
      signIn,
      signOut,
      signUp,
      status: state.status,
      user: state.session?.user ?? null,
      verifyMfa,
    }),
    [confirmTotpEnrollment, refreshSession, signIn, signOut, signUp, state, verifyMfa],
  );

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
}

export function useAuth() {
  const context = useContext(AuthContext);
  if (!context) throw new Error("useAuth must be used within AuthProvider");
  return context;
}

import type { Session } from "@supabase/supabase-js";

import { getSupabaseClient } from "@/lib/supabase";

export type AuthStatus =
  | "authenticated"
  | "error"
  | "loading"
  | "mfa-required"
  | "mfa-setup-required"
  | "signed-out";

export type AuthState = {
  error: Error | null;
  factorId: string | null;
  session: Session | null;
  status: AuthStatus;
};

export type SignUpInput = {
  email: string;
  firstName: string;
  lastName: string;
  password: string;
};

export type SignUpOutcome =
  | { message: null; status: "confirmation-required" }
  | { message: null; status: "signed-up" }
  | { message: string; status: "error" };

export type TotpEnrollment = {
  factorId: string;
  qrCode: string;
  secret: string;
};

export const initialAuthState: AuthState = {
  error: null,
  factorId: null,
  session: null,
  status: "loading",
};

export function createAuthErrorState(error: unknown, session: Session | null): AuthState {
  return {
    error: toError(error, "Your session could not be verified."),
    factorId: null,
    session,
    status: "error",
  };
}

export async function resolveSessionState(session: Session | null): Promise<AuthState> {
  if (!session) {
    return {
      error: null,
      factorId: null,
      session: null,
      status: "signed-out",
    };
  }

  const { data: factors, error: factorsError } = await getSupabaseClient().auth.mfa.listFactors();
  if (factorsError) {
    throw new Error(`Authenticator factors could not be checked: ${factorsError.message}`, {
      cause: factorsError,
    });
  }

  const verifiedTotp = factors.totp
    .filter((factor) => factor.status === "verified")
    .sort((first, second) => first.id.localeCompare(second.id))[0];
  if (!verifiedTotp) {
    return {
      error: null,
      factorId: null,
      session,
      status: "mfa-setup-required",
    };
  }

  const { data: assurance, error: assuranceError } =
    await getSupabaseClient().auth.mfa.getAuthenticatorAssuranceLevel();
  if (assuranceError) {
    throw new Error(`Authenticator assurance could not be checked: ${assuranceError.message}`, {
      cause: assuranceError,
    });
  }

  if (assurance.currentLevel === "aal2") {
    return {
      error: null,
      factorId: null,
      session,
      status: "authenticated",
    };
  }

  if (assurance.currentLevel === "aal1" && assurance.nextLevel === "aal2") {
    return {
      error: null,
      factorId: verifiedTotp.id,
      session,
      status: "mfa-required",
    };
  }

  throw new Error("The session did not provide the required MFA assurance level.");
}

export async function startTotpEnrollment(friendlyName: string): Promise<TotpEnrollment> {
  const { data: factors, error: factorsError } = await getSupabaseClient().auth.mfa.listFactors();
  if (factorsError) {
    throw new Error(
      `Authenticator factors could not be checked: ${describeAuthError(factorsError.message)}`,
      { cause: factorsError },
    );
  }

  // Supabase refuses a new enrollment while abandoned unverified factors remain on the account.
  const unverified = factors.all.filter((factor) => factor.status === "unverified");
  await Promise.all(
    unverified.map(async (factor) => {
      const { error } = await getSupabaseClient().auth.mfa.unenroll({ factorId: factor.id });
      if (error) {
        throw new Error(
          `A previous authenticator could not be removed: ${describeAuthError(error.message)}`,
          { cause: error },
        );
      }
    }),
  );

  const { data, error } = await getSupabaseClient().auth.mfa.enroll({
    factorType: "totp",
    friendlyName,
  });
  if (error) {
    throw new Error(`Authenticator enrollment failed: ${describeAuthError(error.message)}`, {
      cause: error,
    });
  }

  return { factorId: data.id, qrCode: data.totp.qr_code, secret: data.totp.secret };
}

export async function challengeAndVerifyTotp(factorId: string, code: string) {
  const { data: challenge, error: challengeError } = await getSupabaseClient().auth.mfa.challenge({
    factorId,
  });
  if (challengeError) return describeAuthError(challengeError.message);

  const { error: verifyError } = await getSupabaseClient().auth.mfa.verify({
    challengeId: challenge.id,
    code,
    factorId,
  });
  return verifyError ? describeAuthError(verifyError.message) : null;
}

// Supabase reports 5xx replies by stringifying the whole Response object, so the server's real
// message is lost and `error.message` arrives as "{}". Never show that to an operator.
const opaqueAuthFailure =
  "The authentication service rejected the request without explaining why. Try again, or contact a Stitch administrator if it keeps happening.";

export function describeAuthError(
  message: string | null | undefined,
  fallback = opaqueAuthFailure,
) {
  const described = message?.trim();
  return !described || described === "{}" ? fallback : described;
}

export function toError(error: unknown, fallback: string) {
  return error instanceof Error ? error : new Error(fallback, { cause: error });
}

export function isStitchEmail(email: string | null | undefined) {
  return email?.trim().toLowerCase().endsWith("@stitchstudio.ai") ?? false;
}

"use client";

import type { ReactNode } from "react";
import { Navigate, Outlet, useLocation } from "react-router";

import { isStitchEmail } from "@/auth/authorization";
import { useAuth } from "@/auth/auth-provider";
import { Spinner } from "@/components/ui/spinner";

export function ProtectedRoute() {
  const auth = useAuth();
  const location = useLocation();

  if (auth.loading) return <FullPageSpinner label="Loading your session" />;
  if (auth.status !== "authenticated") {
    return <Navigate replace state={{ from: location }} to="/auth" />;
  }
  return <Outlet />;
}

export function StitchOnlyRoute() {
  const auth = useAuth();
  return (
    <StitchEmailGate email={auth.user?.email}>
      <Outlet />
    </StitchEmailGate>
  );
}

export function StitchEmailGate({
  children,
  email,
}: {
  children: ReactNode;
  email: string | null | undefined;
}) {
  return isStitchEmail(email) ? children : <Navigate replace to="/" />;
}

export function FullPageSpinner({ label }: { label: string }) {
  return (
    <div className="grid min-h-svh place-items-center bg-background">
      <div
        aria-live="polite"
        className="flex items-center gap-2 text-sm text-muted-foreground"
        role="status"
      >
        <Spinner aria-hidden="true" className="size-4" />
        {label}
      </div>
    </div>
  );
}

"use client";

import { type FormEvent, useState } from "react";

import { AuthError } from "@/auth/auth-error";
import { useAuth } from "@/auth/auth-provider";
import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";

const minimumPasswordLength = 8;

export function SignUpForm() {
  const auth = useAuth();
  const [confirmationEmail, setConfirmationEmail] = useState("");
  const [email, setEmail] = useState("");
  const [error, setError] = useState("");
  const [firstName, setFirstName] = useState("");
  const [lastName, setLastName] = useState("");
  const [password, setPassword] = useState("");
  const [submitting, setSubmitting] = useState(false);

  async function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setError("");

    const trimmedFirstName = firstName.trim();
    const trimmedLastName = lastName.trim();
    if (!trimmedFirstName || !trimmedLastName) {
      setError("Enter your first and last name.");
      return;
    }
    if (password.length < minimumPasswordLength) {
      setError(`Password must be at least ${minimumPasswordLength} characters.`);
      return;
    }

    const trimmedEmail = email.trim();
    setSubmitting(true);
    try {
      const outcome = await auth.signUp({
        email: trimmedEmail,
        firstName: trimmedFirstName,
        lastName: trimmedLastName,
        password,
      });
      if (outcome.status === "error") setError(outcome.message);
      if (outcome.status === "confirmation-required") setConfirmationEmail(trimmedEmail);
    } catch (cause) {
      setError(cause instanceof Error ? cause.message : "Sign up failed.");
    } finally {
      setSubmitting(false);
    }
  }

  if (confirmationEmail) {
    return (
      <div className="pt-1">
        <Alert>
          <AlertTitle>Confirm your email</AlertTitle>
          <AlertDescription>
            We sent a confirmation link to {confirmationEmail}. Open it, then sign in to set up your
            authenticator.
          </AlertDescription>
        </Alert>
      </div>
    );
  }

  return (
    <form className="space-y-4 pt-1" onSubmit={submit}>
      <div className="grid grid-cols-2 gap-3">
        <div className="space-y-1.5">
          <Label htmlFor="first-name">First name</Label>
          <Input
            autoComplete="given-name"
            id="first-name"
            onChange={(event) => setFirstName(event.target.value)}
            required
            value={firstName}
          />
        </div>
        <div className="space-y-1.5">
          <Label htmlFor="last-name">Last name</Label>
          <Input
            autoComplete="family-name"
            id="last-name"
            onChange={(event) => setLastName(event.target.value)}
            required
            value={lastName}
          />
        </div>
      </div>
      <div className="space-y-1.5">
        <Label htmlFor="sign-up-email">Email</Label>
        <Input
          autoComplete="email"
          id="sign-up-email"
          onChange={(event) => setEmail(event.target.value)}
          required
          type="email"
          value={email}
        />
      </div>
      <div className="space-y-1.5">
        <Label htmlFor="sign-up-password">Password</Label>
        <Input
          autoComplete="new-password"
          id="sign-up-password"
          minLength={minimumPasswordLength}
          onChange={(event) => setPassword(event.target.value)}
          required
          type="password"
          value={password}
        />
        <p className="text-xs text-muted-foreground">
          At least {minimumPasswordLength} characters.
        </p>
      </div>
      {error ? <AuthError message={error} /> : null}
      <Button className="w-full" disabled={submitting} type="submit">
        {submitting ? "Creating account…" : "Create account"}
      </Button>
    </form>
  );
}

"use client";

import { CaretDownIcon, CaretRightIcon } from "@phosphor-icons/react";
import { type FormEvent, useCallback, useEffect, useRef, useState } from "react";

import { AuthError } from "@/auth/auth-error";
import { useAuth } from "@/auth/auth-provider";
import { startTotpEnrollment, type TotpEnrollment } from "@/auth/auth-state";
import { Button } from "@/components/ui/button";
import { Collapsible, CollapsibleContent, CollapsibleTrigger } from "@/components/ui/collapsible";
import { CopyButton } from "@/components/ui/copy-button";
import { InputOTP, InputOTPGroup, InputOTPSlot } from "@/components/ui/input-otp";
import { Label } from "@/components/ui/label";
import { Spinner } from "@/components/ui/spinner";

export function TotpEnrollmentForm({
  appName,
  onSignOut,
  signingOut,
}: {
  appName: string;
  onSignOut: () => void;
  signingOut: boolean;
}) {
  const auth = useAuth();
  const [code, setCode] = useState("");
  const [enrolling, setEnrolling] = useState(true);
  const [enrollment, setEnrollment] = useState<TotpEnrollment | null>(null);
  const [error, setError] = useState("");
  const [secretVisible, setSecretVisible] = useState(false);
  const [submitting, setSubmitting] = useState(false);
  const requested = useRef(false);

  const beginEnrollment = useCallback(async () => {
    setEnrolling(true);
    setError("");
    try {
      setEnrollment(await startTotpEnrollment(appName));
    } catch (cause) {
      setEnrollment(null);
      setError(cause instanceof Error ? cause.message : "Authenticator setup failed.");
    } finally {
      setEnrolling(false);
    }
  }, [appName]);

  // Enrolling twice would strand the secret the operator already scanned.
  useEffect(() => {
    if (requested.current) return;
    requested.current = true;
    void beginEnrollment();
  }, [beginEnrollment]);

  async function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (!enrollment) return;
    setError("");
    setSubmitting(true);
    try {
      const message = await auth.confirmTotpEnrollment(enrollment.factorId, code);
      if (message) {
        setError(message);
        setCode("");
      }
    } catch (cause) {
      setError(cause instanceof Error ? cause.message : "Authenticator verification failed.");
    } finally {
      setSubmitting(false);
    }
  }

  if (enrolling) {
    return (
      <div
        aria-live="polite"
        className="flex items-center justify-center gap-2 py-6 text-sm text-muted-foreground"
        role="status"
      >
        <Spinner aria-hidden="true" className="size-4" />
        Preparing your authenticator
      </div>
    );
  }

  if (!enrollment) {
    return (
      <div className="space-y-4 pt-1">
        <AuthError message={error || "Your authenticator could not be set up."} />
        <div className="flex gap-2">
          <Button
            className="flex-1"
            disabled={signingOut}
            onClick={onSignOut}
            type="button"
            variant="outline"
          >
            {signingOut ? "Signing out…" : "Sign out"}
          </Button>
          <Button className="flex-1" onClick={() => void beginEnrollment()} type="button">
            Try again
          </Button>
        </div>
      </div>
    );
  }

  return (
    <form className="space-y-4 pt-1" onSubmit={submit}>
      <div className="flex flex-col items-center gap-3">
        <div className="rounded-lg border border-border-subtle bg-white p-3">
          <img alt="Authenticator enrollment QR code" className="size-40" src={enrollment.qrCode} />
        </div>
        <Collapsible
          className="w-full space-y-1.5"
          onOpenChange={setSecretVisible}
          open={secretVisible}
        >
          <div className="flex justify-center">
            <CollapsibleTrigger render={<Button size="sm" variant="ghost" />}>
              {secretVisible ? <CaretDownIcon /> : <CaretRightIcon />}
              Can’t scan? Enter this key instead.
            </CollapsibleTrigger>
          </div>
          <CollapsibleContent>
            <CopyButton
              className="h-auto w-full justify-between px-3 py-2 whitespace-normal"
              label="setup key"
              size="default"
              value={enrollment.secret}
              variant="outline"
            >
              <code className="font-mono text-xs break-all">{enrollment.secret}</code>
            </CopyButton>
          </CollapsibleContent>
        </Collapsible>
      </div>
      <div className="space-y-1.5">
        <Label className="block text-center" htmlFor="enrollment-code">
          Authentication code
        </Label>
        <div className="flex justify-center">
          <InputOTP
            autoComplete="one-time-code"
            disabled={submitting}
            id="enrollment-code"
            maxLength={6}
            onChange={setCode}
            value={code}
          >
            <InputOTPGroup>
              {Array.from({ length: 6 }, (_, index) => (
                <InputOTPSlot index={index} key={index} />
              ))}
            </InputOTPGroup>
          </InputOTP>
        </div>
      </div>
      {error ? <AuthError message={error} /> : null}
      <div className="flex gap-2">
        <Button
          className="flex-1"
          disabled={submitting || signingOut}
          onClick={onSignOut}
          type="button"
          variant="outline"
        >
          Sign out
        </Button>
        <Button className="flex-1" disabled={submitting || code.length !== 6} type="submit">
          {submitting ? "Verifying…" : "Enable"}
        </Button>
      </div>
    </form>
  );
}
